/* Original vector artwork created for this prototype; no film posters or third-party images. */
window.ART = (kind=0, wide=false) => {
 const palettes=[['#203b40','#809c8c','#e4b785','#091e24'],['#202b3e','#556f8c','#b5c1bd','#141c2c'],['#4b2e2a','#b87e55','#eed6a2','#281c1d'],['#173b39','#6e9f7a','#e0c89a','#102820'],['#3a3044','#8e6c79','#dfb4aa','#211b30'],['#32372c','#9aa885','#e2dfaf','#20261e'],['#142d3d','#44758c','#c4cdbf','#10202e'],['#4d3b2d','#a28967','#ecdaa9','#29241e']];
 const p=palettes[kind%palettes.length], id='a'+Math.random().toString(36).slice(2),w=wide?1400:400,h=wide?650:600;
 const landscape = kind%4===0 ? `<path d="M0 ${h*.58} Q${w*.17} ${h*.34} ${w*.34} ${h*.57} L${w*.52} ${h*.53} Q${w*.67} ${h*.25} ${w*.84} ${h*.55} L${w} ${h*.53} V${h} H0Z" fill="${p[0]}"/><path d="M0 ${h*.72} Q${w*.25} ${h*.56} ${w*.46} ${h*.71} Q${w*.78} ${h*.54} ${w} ${h*.67} V${h} H0Z" fill="${p[3]}"/><path d="M${w*.57} ${h*.5} L${w*.55} ${h*.91} L${w*.71} ${h*.91} L${w*.65} ${h*.5} Z" fill="${p[2]}" opacity=".22"/>` : kind%4===1 ? `<g fill="${p[3]}">${Array.from({length:11},(_,i)=>`<rect x="${i*w/10-20}" y="${h*(.28+(i%4)*.08)}" width="${w/11}" height="${h}"/><path d="M${i*w/10} ${h*.45} v${h*.35}" stroke="${p[2]}" stroke-width="2" opacity=".3"/>`).join('')}</g><path d="M${w*.49} ${h*.55}L${w*.2} ${h}H${w*.8}L${w*.54} ${h*.55}" fill="${p[1]}" opacity=".25"/>` : kind%4===2 ? `<path d="M0 ${h*.58} Q${w*.2} ${h*.27} ${w*.6} ${h*.6} T${w*1.2} ${h*.55}V${h}H0Z" fill="${p[1]}"/><path d="M0 ${h*.75} Q${w*.3} ${h*.43} ${w*.75} ${h*.75} T${w*1.4} ${h*.7}V${h}H0Z" fill="${p[0]}"/><path d="M0 ${h*.9}Q${w*.6} ${h*.57} ${w} ${h*.9} V${h}H0Z" fill="${p[3]}"/>` : `<g fill="${p[3]}" opacity=".7">${Array.from({length:18},(_,i)=>`<path d="M${i*w/16} ${h*.15+(i%3)*40}l-${w*.08} ${h*.65}h${w*.16}Z"/>`).join('')}</g><path d="M${w*.5} ${h*.6}Q${w*.42} ${h*.8} ${w*.66} ${h}H${w*.3}Q${w*.62} ${h*.78} ${w*.5} ${h*.6}" fill="${p[2]}" opacity=".35"/>`;
 return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="${id}" x2="0" y2="1"><stop stop-color="${p[0]}"/><stop offset=".6" stop-color="${p[1]}"/><stop offset="1" stop-color="${p[3]}"/></linearGradient><radialGradient id="${id}g"><stop stop-color="${p[2]}" stop-opacity=".65"/><stop offset="1" stop-color="${p[2]}" stop-opacity="0"/></radialGradient><filter id="${id}n"><feTurbulence type="fractalNoise" baseFrequency=".65" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".065"/></feComponentTransfer><feBlend in="SourceGraphic" mode="soft-light"/></filter></defs><rect width="100%" height="100%" fill="url(#${id})"/><ellipse cx="${w*.69}" cy="${h*.35}" rx="${w*.45}" ry="${h*.55}" fill="url(#${id}g)"/><circle cx="${w*.7}" cy="${h*.3}" r="${wide?66:48}" fill="${p[2]}" opacity=".7"/>${landscape}<path d="M${w*.51} ${h*.81}v${h*.035}m-4 0h8" stroke="${p[3]}" stroke-width="${wide?6:4}"/><rect width="100%" height="100%" filter="url(#${id}n)" opacity=".4"/></svg>`;
};
